package bottlesong

import "unicode"

var numberWords = map[int]string{
	0:  "no",
	1:  "one",
	2:  "two",
	3:  "three",
	4:  "four",
	5:  "five",
	6:  "six",
	7:  "seven",
	8:  "eight",
	9:  "nine",
	10: "ten",
}

// bottlePhrase returns the lowercase phrase for a given bottle count,
// using the singular form for one bottle and the plural form otherwise.
// Example: "one green bottle", "ten green bottles", "no green bottles".
func bottlePhrase(n int) string {
	if n == 1 {
		return "one green bottle"
	}
	return numberWords[n] + " green bottles"
}

// capitalize uppercases the first rune of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

// verse returns the four lines of the verse for the given bottle count.
func verse(n int) []string {
	return []string{
		capitalize(bottlePhrase(n)) + " hanging on the wall,",
		capitalize(bottlePhrase(n)) + " hanging on the wall,",
		"And if one green bottle should accidentally fall,",
		"There'll be " + bottlePhrase(n-1) + " hanging on the wall.",
	}
}

// Recite returns the lyrics for takeDown consecutive verses, starting
// from startBottles bottles. Verses are separated by a blank line.
func Recite(startBottles, takeDown int) []string {
	var result []string
	for i := 0; i < takeDown; i++ {
		if i > 0 {
			result = append(result, "")
		}
		result = append(result, verse(startBottles-i)...)
	}
	return result
}
